let entry = find_symbols("JNI_OnLoad");
for s in entry {
  report("JNI_OnLoad Entry", s.address, "INFO", "Size: " + s.size + " bytes");
  let insns = disasm(s.address, 256);
  let n = insns.len();
  for i in 0..n {
    let ins = insns[i];
    if ins.mnemonic == "bl" || ins.mnemonic == "blr" {
      report("JNI_OnLoad Call", ins.address, "INFO", ins.mnemonic + " " + ins.op_str);
    }
    if ins.op_str.contains("0x6b8") || ins.op_str.contains("0x35c") {
      let dispatched = false;
      let j = i + 1;
      while j < n && j <= i + 32 {
        let m = insns[j].mnemonic;
        if m == "blr" || m == "bl" {
          dispatched = true;
          break;
        }
        j += 1;
      }
      if dispatched {
        report("RegisterNatives VTable", ins.address, "HIGH", ins.mnemonic + " " + ins.op_str + " (call dispatch follows)");
      }
    }
  }
}
let exports = find_symbols("Java_");
for s in exports {
  if s.name.starts_with("Java_") {
    report("Java_ Export", s.address, "INFO", s.name);
  }
}
let methods = find_jni_methods();
for m in methods {
  report("JNI: " + m.name, m.address, "HIGH", m.signature);
}
let strs = find_strings("RegisterNatives");
for st in strs {
  report("RegisterNatives String", st.address, "INFO", st.value);
}
